"""Frozen schema assets for revision 3f8b2a1c9d70."""

ASSESSMENT_BOARD_SCHEMA = "\nCREATE TABLE IF NOT EXISTS assessment_boards (\n    board_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    board_type TEXT NOT NULL,\n    name TEXT NOT NULL,\n    academic_year TEXT NOT NULL,\n    programme_code TEXT,\n    module_code TEXT,\n    meeting_at TEXT,\n    status TEXT NOT NULL DEFAULT 'draft',\n    version INTEGER NOT NULL DEFAULT 1,\n    chair_id TEXT,\n    chair_approved_at TEXT,\n    ratified_at TEXT,\n    ratified_by TEXT,\n    reopened_at TEXT,\n    reopened_by TEXT,\n    reopen_reason TEXT,\n    created_by TEXT NOT NULL,\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS assessment_board_members (\n    board_id INTEGER NOT NULL,\n    member_id TEXT NOT NULL,\n    role TEXT NOT NULL,\n    PRIMARY KEY(board_id, member_id),\n    FOREIGN KEY (board_id) REFERENCES assessment_boards(board_id)\n);\n\nCREATE TABLE IF NOT EXISTS assessment_board_rules (\n    rule_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    board_id INTEGER NOT NULL,\n    rule_type TEXT NOT NULL,\n    minimum_mark REAL,\n    maximum_credits REAL,\n    exclude_core_modules INTEGER NOT NULL DEFAULT 1,\n    notes TEXT,\n    active INTEGER NOT NULL DEFAULT 1,\n    FOREIGN KEY (board_id) REFERENCES assessment_boards(board_id)\n);\n\nCREATE TABLE IF NOT EXISTS assessment_board_agenda (\n    agenda_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    board_id INTEGER NOT NULL,\n    student_id TEXT NOT NULL,\n    programme_code TEXT,\n    current_level TEXT,\n    credits REAL,\n    average_mark REAL,\n    proposed_classification TEXT,\n    flags TEXT,\n    status TEXT NOT NULL DEFAULT 'pending',\n    UNIQUE(board_id, student_id),\n    FOREIGN KEY (board_id) REFERENCES assessment_boards(board_id)\n);\n\nCREATE TABLE IF NOT EXISTS assessment_board_decisions (\n    decision_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    board_id INTEGER NOT NULL,\n    student_id TEXT NOT NULL,\n    module_code TEXT,\n    decision_type TEXT NOT NULL,\n    original_result TEXT,\n    confirmed_result TEXT,\n    credits_affected REAL,\n    classification TEXT,\n    rationale TEXT NOT NULL,\n    decided_by TEXT NOT NULL,\n    decided_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    supersedes_decision_id INTEGER,\n    UNIQUE(board_id, student_id, module_code, supersedes_decision_id),\n    FOREIGN KEY (board_id) REFERENCES assessment_boards(board_id)\n);\n\nCREATE TABLE IF NOT EXISTS assessment_board_minutes (\n    board_id INTEGER PRIMARY KEY,\n    minutes_text TEXT NOT NULL,\n    minutes_hash TEXT NOT NULL,\n    locked INTEGER NOT NULL DEFAULT 0,\n    updated_by TEXT NOT NULL,\n    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (board_id) REFERENCES assessment_boards(board_id)\n);\n\nCREATE TABLE IF NOT EXISTS ratified_student_awards (\n    award_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    board_id INTEGER NOT NULL,\n    student_id TEXT NOT NULL,\n    programme_code TEXT NOT NULL,\n    award_name TEXT NOT NULL,\n    classification TEXT,\n    academic_year TEXT NOT NULL,\n    status TEXT NOT NULL DEFAULT 'ratified',\n    ratified_at TEXT NOT NULL,\n    ratified_by TEXT NOT NULL,\n    release_authorised INTEGER NOT NULL DEFAULT 1,\n    superseded_by_award_id INTEGER,\n    UNIQUE(student_id, programme_code, academic_year),\n    FOREIGN KEY (board_id) REFERENCES assessment_boards(board_id)\n);\n\nCREATE TABLE IF NOT EXISTS assessment_board_corrections (\n    correction_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    board_id INTEGER NOT NULL,\n    decision_id INTEGER,\n    reason TEXT NOT NULL,\n    requested_by TEXT NOT NULL,\n    approved_by TEXT NOT NULL,\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (board_id) REFERENCES assessment_boards(board_id)\n);\n"

PROGRAMME_GOVERNANCE_SCHEMA = "\nCREATE TABLE IF NOT EXISTS governed_programmes (\n    programme_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    programme_code TEXT NOT NULL UNIQUE,\n    programme_name TEXT NOT NULL,\n    owning_school TEXT,\n    award_type TEXT NOT NULL,\n    status TEXT NOT NULL DEFAULT 'proposed',\n    created_by TEXT NOT NULL,\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n\nCREATE TABLE IF NOT EXISTS programme_proposals (\n    proposal_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    programme_id INTEGER NOT NULL,\n    rationale TEXT NOT NULL,\n    market_need TEXT,\n    strategic_alignment TEXT,\n    proposed_start_year TEXT NOT NULL,\n    status TEXT NOT NULL DEFAULT 'draft',\n    submitted_at TEXT,\n    submitted_by TEXT,\n    FOREIGN KEY (programme_id) REFERENCES governed_programmes(programme_id)\n);\n\nCREATE TABLE IF NOT EXISTS programme_business_cases (\n    business_case_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    proposal_id INTEGER NOT NULL UNIQUE,\n    forecast_students_json TEXT NOT NULL,\n    income_json TEXT NOT NULL,\n    costs_json TEXT NOT NULL,\n    staffing_plan TEXT,\n    facilities_plan TEXT,\n    risk_register TEXT,\n    approved INTEGER NOT NULL DEFAULT 0,\n    approved_by TEXT,\n    approved_at TEXT,\n    FOREIGN KEY (proposal_id) REFERENCES programme_proposals(proposal_id)\n);\n\nCREATE TABLE IF NOT EXISTS programme_versions (\n    version_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    programme_id INTEGER NOT NULL,\n    version_number INTEGER NOT NULL,\n    effective_academic_year TEXT NOT NULL,\n    end_academic_year TEXT,\n    status TEXT NOT NULL DEFAULT 'draft',\n    curriculum_json TEXT NOT NULL,\n    regulations_json TEXT NOT NULL,\n    snapshot_hash TEXT,\n    validation_outcome TEXT,\n    approved_at TEXT,\n    approved_by TEXT,\n    supersedes_version_id INTEGER,\n    created_by TEXT NOT NULL,\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    UNIQUE(programme_id, version_number),\n    UNIQUE(programme_id, effective_academic_year),\n    FOREIGN KEY (programme_id) REFERENCES governed_programmes(programme_id)\n);\n\nCREATE TABLE IF NOT EXISTS programme_amendments (\n    amendment_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    source_version_id INTEGER NOT NULL,\n    target_version_id INTEGER,\n    amendment_type TEXT NOT NULL,\n    summary TEXT NOT NULL,\n    impact_assessment TEXT NOT NULL,\n    requested_by TEXT NOT NULL,\n    status TEXT NOT NULL DEFAULT 'proposed',\n    decided_by TEXT,\n    decided_at TEXT,\n    FOREIGN KEY (source_version_id) REFERENCES programme_versions(version_id)\n);\n\nCREATE TABLE IF NOT EXISTS approval_committees (\n    committee_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    name TEXT NOT NULL UNIQUE,\n    committee_type TEXT NOT NULL,\n    quorum INTEGER NOT NULL,\n    active INTEGER NOT NULL DEFAULT 1\n);\n\nCREATE TABLE IF NOT EXISTS programme_validations (\n    validation_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    version_id INTEGER NOT NULL,\n    committee_id INTEGER NOT NULL,\n    meeting_at TEXT NOT NULL,\n    members_json TEXT NOT NULL,\n    external_advisers_json TEXT NOT NULL DEFAULT '[]',\n    conditions_json TEXT NOT NULL DEFAULT '[]',\n    outcome TEXT NOT NULL,\n    minutes_reference TEXT NOT NULL,\n    chair_id TEXT NOT NULL,\n    decided_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (version_id) REFERENCES programme_versions(version_id),\n    FOREIGN KEY (committee_id) REFERENCES approval_committees(committee_id)\n);\n\nCREATE TABLE IF NOT EXISTS programme_accreditations (\n    accreditation_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    programme_id INTEGER NOT NULL,\n    version_id INTEGER,\n    body_name TEXT NOT NULL,\n    accreditation_reference TEXT,\n    status TEXT NOT NULL,\n    valid_from TEXT,\n    valid_until TEXT,\n    conditions TEXT,\n    evidence_reference TEXT,\n    FOREIGN KEY (programme_id) REFERENCES governed_programmes(programme_id)\n);\n\nCREATE TABLE IF NOT EXISTS programme_teach_out_plans (\n    plan_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    programme_id INTEGER NOT NULL,\n    version_id INTEGER,\n    last_intake_year TEXT NOT NULL,\n    final_delivery_year TEXT NOT NULL,\n    student_communication TEXT NOT NULL,\n    staffing_commitment TEXT NOT NULL,\n    module_availability_json TEXT NOT NULL,\n    approved_by TEXT NOT NULL,\n    approved_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    status TEXT NOT NULL DEFAULT 'active',\n    FOREIGN KEY (programme_id) REFERENCES governed_programmes(programme_id)\n);\n\nCREATE TABLE IF NOT EXISTS student_regulation_assignments (\n    assignment_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    student_id TEXT NOT NULL,\n    programme_id INTEGER NOT NULL,\n    version_id INTEGER NOT NULL,\n    assigned_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    assigned_by TEXT NOT NULL,\n    reason TEXT NOT NULL,\n    active INTEGER NOT NULL DEFAULT 1,\n    FOREIGN KEY (programme_id) REFERENCES governed_programmes(programme_id),\n    FOREIGN KEY (version_id) REFERENCES programme_versions(version_id)\n);\nCREATE UNIQUE INDEX IF NOT EXISTS idx_one_active_student_regulation\nON student_regulation_assignments(student_id, programme_id)\nWHERE active = 1;\n\nCREATE TABLE IF NOT EXISTS programme_governance_history (\n    history_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    programme_id INTEGER NOT NULL,\n    version_id INTEGER,\n    action TEXT NOT NULL,\n    actor_id TEXT NOT NULL,\n    reason TEXT,\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP\n);\n"

PGR_SCHEMA = "\nCREATE TABLE IF NOT EXISTS pgr_projects (\n    project_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    student_id TEXT NOT NULL,\n    proposal_title TEXT NOT NULL,\n    abstract TEXT NOT NULL,\n    research_questions TEXT,\n    methodology TEXT,\n    department TEXT,\n    route TEXT NOT NULL DEFAULT 'MPhil/PhD',\n    status TEXT NOT NULL DEFAULT 'proposal',\n    start_date TEXT,\n    expected_end_date TEXT,\n    current_deadline TEXT,\n    legacy_thesis_id INTEGER,\n    created_by TEXT NOT NULL,\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    UNIQUE(student_id, proposal_title)\n);\n\nCREATE TABLE IF NOT EXISTS pgr_supervision_team (\n    allocation_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    project_id INTEGER NOT NULL,\n    supervisor_id TEXT NOT NULL,\n    role TEXT NOT NULL,\n    workload_fte REAL NOT NULL,\n    start_date TEXT NOT NULL,\n    end_date TEXT,\n    active INTEGER NOT NULL DEFAULT 1,\n    UNIQUE(project_id, supervisor_id, role),\n    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)\n);\n\nCREATE TABLE IF NOT EXISTS pgr_supervision_meetings (\n    meeting_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    project_id INTEGER NOT NULL,\n    meeting_at TEXT NOT NULL,\n    attendees_json TEXT NOT NULL,\n    progress_summary TEXT NOT NULL,\n    actions_json TEXT NOT NULL,\n    next_meeting_date TEXT,\n    student_confirmed INTEGER NOT NULL DEFAULT 0,\n    supervisor_confirmed INTEGER NOT NULL DEFAULT 0,\n    created_by TEXT NOT NULL,\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)\n);\n\nCREATE TABLE IF NOT EXISTS pgr_training_needs (\n    need_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    project_id INTEGER NOT NULL,\n    category TEXT NOT NULL,\n    description TEXT NOT NULL,\n    priority TEXT NOT NULL DEFAULT 'normal',\n    planned_activity TEXT,\n    target_date TEXT,\n    completed_at TEXT,\n    evidence_reference TEXT,\n    status TEXT NOT NULL DEFAULT 'identified',\n    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)\n);\n\nCREATE TABLE IF NOT EXISTS pgr_progress_reviews (\n    review_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    project_id INTEGER NOT NULL,\n    review_year INTEGER NOT NULL,\n    due_date TEXT NOT NULL,\n    submitted_at TEXT,\n    panel_json TEXT,\n    student_report TEXT,\n    supervisor_report TEXT,\n    outcome TEXT,\n    conditions TEXT,\n    approved_at TEXT,\n    approved_by TEXT,\n    status TEXT NOT NULL DEFAULT 'due',\n    UNIQUE(project_id, review_year),\n    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)\n);\n\nCREATE TABLE IF NOT EXISTS pgr_approvals (\n    approval_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    project_id INTEGER NOT NULL,\n    approval_type TEXT NOT NULL,\n    reference TEXT,\n    risk_level TEXT,\n    status TEXT NOT NULL DEFAULT 'required',\n    submitted_at TEXT,\n    approved_at TEXT,\n    expires_at TEXT,\n    conditions TEXT,\n    approved_by TEXT,\n    UNIQUE(project_id, approval_type, reference),\n    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)\n);\n\nCREATE TABLE IF NOT EXISTS pgr_upgrades (\n    upgrade_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    project_id INTEGER NOT NULL,\n    submitted_at TEXT NOT NULL,\n    report_reference TEXT NOT NULL,\n    panel_json TEXT NOT NULL,\n    outcome TEXT,\n    conditions TEXT,\n    decided_at TEXT,\n    decided_by TEXT,\n    status TEXT NOT NULL DEFAULT 'submitted',\n    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)\n);\n\nCREATE TABLE IF NOT EXISTS pgr_thesis_submissions (\n    submission_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    project_id INTEGER NOT NULL,\n    version INTEGER NOT NULL,\n    thesis_title TEXT NOT NULL,\n    repository_reference TEXT NOT NULL,\n    submitted_at TEXT NOT NULL,\n    declaration_accepted INTEGER NOT NULL,\n    status TEXT NOT NULL DEFAULT 'submitted',\n    UNIQUE(project_id, version),\n    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)\n);\n\nCREATE TABLE IF NOT EXISTS pgr_examiners (\n    nomination_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    project_id INTEGER NOT NULL,\n    examiner_id TEXT NOT NULL,\n    examiner_type TEXT NOT NULL,\n    institution TEXT,\n    expertise TEXT,\n    conflict_declaration TEXT NOT NULL,\n    nominated_by TEXT NOT NULL,\n    status TEXT NOT NULL DEFAULT 'nominated',\n    approved_by TEXT,\n    approved_at TEXT,\n    UNIQUE(project_id, examiner_id),\n    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)\n);\n\nCREATE TABLE IF NOT EXISTS pgr_vivas (\n    viva_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    project_id INTEGER NOT NULL UNIQUE,\n    scheduled_at TEXT NOT NULL,\n    location TEXT,\n    chair_id TEXT,\n    status TEXT NOT NULL DEFAULT 'scheduled',\n    outcome TEXT,\n    outcome_notes TEXT,\n    decided_at TEXT,\n    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)\n);\n\nCREATE TABLE IF NOT EXISTS pgr_corrections (\n    correction_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    project_id INTEGER NOT NULL,\n    correction_type TEXT NOT NULL,\n    description TEXT NOT NULL,\n    due_date TEXT NOT NULL,\n    submitted_at TEXT,\n    approved_at TEXT,\n    approved_by TEXT,\n    status TEXT NOT NULL DEFAULT 'outstanding',\n    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)\n);\n\nCREATE TABLE IF NOT EXISTS pgr_final_deposits (\n    deposit_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    project_id INTEGER NOT NULL UNIQUE,\n    repository_reference TEXT NOT NULL,\n    deposited_at TEXT NOT NULL,\n    embargo_until TEXT,\n    licence TEXT NOT NULL,\n    checked_by TEXT NOT NULL,\n    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)\n);\n\nCREATE TABLE IF NOT EXISTS pgr_milestones (\n    milestone_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    project_id INTEGER NOT NULL,\n    milestone_type TEXT NOT NULL,\n    title TEXT NOT NULL,\n    due_date TEXT NOT NULL,\n    completed_at TEXT,\n    status TEXT NOT NULL DEFAULT 'pending',\n    extension_until TEXT,\n    extension_reason TEXT,\n    extension_approved_by TEXT,\n    UNIQUE(project_id, milestone_type, title),\n    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)\n);\n\nCREATE TABLE IF NOT EXISTS pgr_history (\n    history_id INTEGER PRIMARY KEY AUTOINCREMENT,\n    project_id INTEGER NOT NULL,\n    action TEXT NOT NULL,\n    from_status TEXT,\n    to_status TEXT,\n    actor_id TEXT NOT NULL,\n    reason TEXT,\n    metadata_json TEXT NOT NULL DEFAULT '{}',\n    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    FOREIGN KEY (project_id) REFERENCES pgr_projects(project_id)\n);\n"

FEATURE_SCHEMAS = (
    ASSESSMENT_BOARD_SCHEMA,
    PROGRAMME_GOVERNANCE_SCHEMA,
    PGR_SCHEMA,
)
